mapper.select:
SELECT count(*) from T_STAFF_VEHI as tsv,T_STAFF as ts where
tsv.sfvh_staff_id = ts.staff_id and
ts.staff_airport_code = #{staffAirportCode}
and sfvh_staff_status =1

    and ts.staff_aptarea_code = #{staffAptareaCode}

SELECT count(*) from T_STAFF_VEHI as tsv,T_STAFF as ts where
tsv.sfvh_staff_id = ts.staff_id and
ts.staff_airport_code = #{staffAirportCode}
and sfvh_staff_status =2

    and ts.staff_aptarea_code = #{staffAptareaCode}

select sfvh_staff_id as staffId
from T_STAFF_VEHI
where sfvh_vehi_no = #{vehiNo}

select staff_name as staffName, staff_phone as staffPhone
from T_STAFF
where staff_id = #{vehiStaffId}

select vehi_fuel_code
from T_VEHI
where vehi_airport_code = #{vehiAirportCode}
  and vehi_plate_no = #{vehiPlateNo}

select vehi_fuel_code as vehiFuelCode,
       vehi_fuel_sno  as vehiFuelSno,
       vehi_no        as vehiNo
from T_VEHI
where vehi_airport_code = #{vehiAirportCode}
  and vehi_plate_no = #{vehiPlateNo}

mapper.update:
UPDATE T_VEHI
SET vehi_fuel_sno=#{vehiFuelSno}
where vehi_airport_code = #{vehiAirportCode}
  and vehi_plate_no = #{vehiPlateNo}
